_MODULES_BY_ID: dict[int, ShipModule] = {_m.fdev_id: _m for _m in _MODULES_BY_SYMBOL.values()}


class StaticModuleCatalogAdapter(ModuleCatalogProviderPort):
    """In-memory static catalog provider for outfitting modules."""

    def get_module_by_id(self, fdev_id: int) -> ShipModule | None:
        return _MODULES_BY_ID.get(fdev_id)

    def get_module_by_symbol(self, symbol: str) -> ShipModule | None:
        return _MODULES_BY_SYMBOL.get(symbol.lower())
